// Accessible 2D view of the same model/flow data. No renderer, network call or WebGL required.
const NS='http://www.w3.org/2000/svg';
export function drawCityMap(host,{nodes,ids,steps,index,onSelect,onStep,city=false,progress=null,stepLimit=null,blocked=false,failureNote=''}){
 const make=(tag,attrs={},text)=>{const e=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;return e;};
 const visible=ids.filter(id=>nodes.some(n=>n.id===id)),positions=new Map(visible.map((id,i)=>[id,{x:45+(i%4)*245,y:55+Math.floor(i/4)*135}]));const height=Math.max(260,Math.ceil(visible.length/4)*135+45);
 const routeColor=blocked?'#ff7799':'#6be5ff';const svg=make('svg',{viewBox:`0 0 1000 ${height}`,role:'group','aria-label':city?'Map of connected DevOps towns':'Map of the current components and directed connection'});const defs=make('defs'),marker=make('marker',{id:'city-map-arrow',viewBox:'0 0 10 10',refX:9,refY:5,markerWidth:7,markerHeight:7,orient:'auto-start-reverse'});marker.append(make('path',{d:'M 0 0 L 10 5 L 0 10 z',fill:routeColor}));defs.append(marker);svg.append(defs);
 if(progress!==null){svg.append(make('circle',{cx:500,cy:height/2,r:Math.max(1,progress*Math.hypot(500,height/2)),fill:'none',stroke:'#ffb65c','stroke-width':3,opacity:.6}));}
 const step=steps[index],a=positions.get(step?.from),b=positions.get(step?.to);if(a&&b){svg.append(make('path',{d:`M ${a.x+100} ${a.y+40} Q ${(a.x+b.x)/2+100} ${Math.min(a.y,b.y)-35} ${b.x+100} ${b.y+40}`,fill:'none',stroke:routeColor,'stroke-width':3,'stroke-dasharray':step.relation==='network'?'none':'7 5','marker-end':'url(#city-map-arrow)'}));}
 for(const id of visible){const n=nodes.find(n=>n.id===id),p=positions.get(id),g=make('g',{role:'button',tabindex:0,'aria-label':'Inspect '+n.label});g.append(make('rect',{x:p.x,y:p.y,width:205,height:80,rx:12,fill:step&&(id===step.from||id===step.to)?'#2e5b70':'#202e49',stroke:n.district?'#b9a6e8':'#729fba','stroke-width':2}));const words=n.label.split(' '),lines=[''];for(const word of words){let i=lines.length-1;if((lines[i]+' '+word).length>24&&lines[i]){lines.push(word);}else lines[i]+=(lines[i]?' ':'')+word;}lines.slice(0,2).forEach((line,i)=>g.append(make('text',{x:p.x+12,y:p.y+25+i*19,fill:'#e1f4ff','font-size':13,'font-family':'system-ui'},line)));g.append(make('text',{x:p.x+12,y:p.y+66,fill:'#9fbed1','font-size':10,'font-family':'system-ui'},n.district?'TOWN · SELECT TO EXPLORE':n.kind.toUpperCase()));g.addEventListener('click',()=>onSelect(id));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onSelect(id);}});svg.append(g);}
 const title=document.createElement('h3');title.textContent=(blocked?'2D map · Blocked · ':'2D map · ')+(step?.title||'Explore the city');const note=document.createElement('p');note.textContent=blocked?'No successful application response is implied. '+failureNote:step?step.text+' '+step.packet:'Select a town to inspect it.';const controls=document.createElement('div');for(const [label,next]of [['Previous connection',index-1],['Next connection',index+1]]){const btn=document.createElement('button');btn.textContent=label;btn.disabled=next<0||next>=steps.length||(stepLimit!==null&&stepLimit!==undefined&&next>stepLimit);btn.addEventListener('click',()=>onStep(next));controls.append(btn);}host.replaceChildren(title,svg,note,controls);
}
